def norm_upper(v: Any) -> str:
    return norm_str(v).upper()


def is_blank(v: Any) -> bool:
    if v is None:
        return True
    if isinstance(v, str) and v.strip() == "":
        return True
    return False


def to_number(v: Any) -> Optional[float]:
    if v is None:
        return None
    if isinstance(v, (int, float)):
        # NaN check (NaN != NaN)
        if isinstance(v, float) and v != v:
            return None
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if s == "":
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None


def copy_worksheet_cell_by_cell(src_ws: Worksheet, dst_ws: Worksheet) -> None:
    """Copy worksheet content and formatting as closely as possible."""

    # Sheet-level properties (best-effort; openpyxl does not support every bit-perfect clone).
    dst_ws.sheet_format = copy(src_ws.sheet_format)
    dst_ws.sheet_properties = copy(src_ws.sheet_properties)
    dst_ws.page_margins = copy(src_ws.page_margins)
    dst_ws.page_setup = copy(src_ws.page_setup)
    dst_ws.print_options = copy(src_ws.print_options)
    dst_ws.sheet_view = copy(src_ws.sheet_view)

    # Dimensions
    for col_letter, dim in src_ws.column_dimensions.items():
        dst_dim = dst_ws.column_dimensions[col_letter]
        dst_dim.width = dim.width
        dst_dim.hidden = dim.hidden
        dst_dim.outlineLevel = dim.outlineLevel
        dst_dim.collapsed = dim.collapsed

    for row_idx, dim in src_ws.row_dimensions.items():
        dst_dim = dst_ws.row_dimensions[row_idx]
        dst_dim.height = dim.height
        dst_dim.hidden = dim.hidden
        dst_dim.outlineLevel = dim.outlineLevel
        dst_dim.collapsed = dim.collapsed

    # Copy cells
    max_row = src_ws.max_row
    max_col = src_ws.max_column

    for r in range(1, max_row + 1):
        for c in range(1, max_col + 1):
            src_cell = src_ws.cell(row=r, column=c)
            # Avoid touching merged non-master cells.
            if isinstance(src_cell, MergedCell):
                continue

            dst_cell = dst_ws.cell(row=r, column=c, value=src_cell.value)

            if src_cell.has_style:
                dst_cell.font = copy(src_cell.font)
                dst_cell.fill = copy(src_cell.fill)
                dst_cell.border = copy(src_cell.border)
                dst_cell.alignment = copy(src_cell.alignment)
                dst_cell.number_format = src_cell.number_format
                dst_cell.protection = copy(src_cell.protection)
                dst_cell._style = copy(src_cell._style)

            dst_cell.comment = copy(src_cell.comment) if src_cell.comment else None
            dst_cell.hyperlink = copy(src_cell.hyperlink) if src_cell.hyperlink else None

    # Merged cells
    for merged_range in src_ws.merged_cells.ranges:
        dst_ws.merge_cells(str(merged_range))

    # Freeze panes
    dst_ws.freeze_panes = src_ws.freeze_panes


def read_table_from_sheet(ws: Worksheet) -> Tuple[List[str], List[List[Any]]]:
    """Return (headers, rows) for a rectangular table based on ws.max_row/max_column."""
    headers = [ws.cell(row=1, column=c).value for c in range(1, ws.max_column + 1)]
    headers_str = [norm_str(h) for h in headers]

    rows: List[List[Any]] = []
    for r in range(2, ws.max_row + 1):
        row = [ws.cell(row=r, column=c).value for c in range(1, ws.max_column + 1)]
        rows.append(row)

    return headers_str, rows


def build_final_count_lookup(events_ws: Worksheet) -> Tuple[Dict[Tuple[str, str, str], float], int, int]:
    """Build lookup key (Facility, Session ID, Bin ID) -> Count Qty for latest FINAL event.

    Returns: (lookup, final_rows_seen, final_rows_kept)
    """

    headers, rows = read_table_from_sheet(events_ws)
    idx = {h: i for i, h in enumerate(headers)}

    for required in ["Facility", "Session ID", "Bin ID", "Event Type", "Count Qty"]:
        if required not in idx:
            raise ValueError(f"Event log missing required column: {required}")

    lookup: Dict[Tuple[str, str, str], float] = {}
    final_rows_seen = 0

    for row in rows:
        event_type = norm_upper(row[idx["Event Type"]])
        if event_type != "FINAL":
            continue
        final_rows_seen += 1

        facility = norm_str(row[idx["Facility"]])
        session_id = norm_str(row[idx["Session ID"]])
        bin_id = norm_str(row[idx["Bin ID"]])

        if is_blank(facility) or is_blank(session_id) or is_blank(bin_id):
            continue

        qty = to_number(row[idx["Count Qty"]])
        if qty is None:
            continue

        key = (facility, session_id, bin_id)
        # Iterating in original row order: later assignments overwrite earlier ones,
        # which matches "keep only the LAST row (highest original index)".
        lookup[key] = qty

    return lookup, final_rows_seen, len(lookup)


